function sortArray(nums) {
  const out = nums.slice();
  for (let i = 0; i < out.length; i++) {
    let smallest = i;
    for (let j = i + 1; j < out.length; j++) {
      if (out[j] < out[smallest]) smallest = j;
    }
    const swap = out[i];
    out[i] = out[smallest];
    out[smallest] = swap;
  }
  return out;
}

