function sortArray(nums) {
  const out = nums.slice();
  for (let i = 1; i < out.length; i++) {
    const value = out[i];
    let j = i - 1;
    while (j >= 0 && out[j] > value) {
      out[j + 1] = out[j];
      j -= 1;
    }
    out[j + 1] = value;
  }
  return out;
}

