function countAdjacentSwaps(nums) {
  const out = nums.slice();
  let swaps = 0;
  let moved = true;
  while (moved) {
    moved = false;
    for (let i = 0; i + 1 < out.length; i++) {
      if (out[i] > out[i + 1]) {
        const swap = out[i];
        out[i] = out[i + 1];
        out[i + 1] = swap;
        swaps += 1;
        moved = true;
      }
    }
  }
  return swaps;
}

