def count_adjacent_swaps(nums):
    out = list(nums)
    swaps = 0
    moved = True
    while moved:
        moved = False
        for i in range(len(out) - 1):
            if out[i] > out[i + 1]:
                out[i], out[i + 1] = out[i + 1], out[i]
                swaps += 1
                moved = True
    return swaps

